#!/usr/bin/env node
/**
 * Generates src/generated/volumes.ts from tech-radar-json-data/.
 *
 * Cloudflare Workers have no filesystem, so the volume JSON files cannot be
 * read with fs at runtime — they have to be statically imported so the bundler
 * inlines them. This script emits those imports.
 *
 * Re-run it (`npm run gen:volumes`) whenever a volume is added or removed.
 * `tests/volumesManifest.test.ts` fails if the generated file is out of date.
 */
import { mkdir, readdir, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const dataDir = join(root, 'tech-radar-json-data')
const outFile = join(root, 'src', 'generated', 'volumes.ts')

const files = (await readdir(dataDir)).filter((f) => f.endsWith('.json')).sort()

if (files.length === 0) {
  throw new Error(`No .json volumes found in ${dataDir}`)
}

// `with { type: 'json' }` is required by tsc under module: NodeNext, and is
// understood by esbuild (wrangler) and vite (vitest).
const imports = files.map(
  (f, i) => `import vol${i} from '../../tech-radar-json-data/${f}' with { type: 'json' }`,
)

const entries = files.map(
  (f, i) => `  { filename: ${JSON.stringify(f)}, entries: vol${i} as RawEntry[] },`,
)

const output = `// AUTO-GENERATED by scripts/gen-volumes.ts — do not edit by hand.
// Regenerate with: npm run gen:volumes
import type { RawEntry } from '../types.js'
${imports.join('\n')}

export const VOLUMES: Array<{ filename: string; entries: RawEntry[] }> = [
${entries.join('\n')}
]
`

await mkdir(dirname(outFile), { recursive: true })
await writeFile(outFile, output, 'utf-8')

console.log(`Wrote ${outFile} (${files.length} volumes)`)
